  function exitCar() {
    const p = state.player;
    const car = state.cars[p.carId];
    if (!car) return 0;
    const sx = car.x + Math.cos(car.angle + Math.PI / 2) * 2;
    const sz = car.z + Math.sin(car.angle + Math.PI / 2) * 2;
    const fixed = collideCircle(sx, sz, PLAYER.radius, city.colliders);
    p.x = fixed.x;
    p.z = fixed.z;
